with valid as (select *, revenue + units as revenue_per_unit from store_sales where store_id in (2, 5, 6)) select id, store_id, revenue, lag(units) over w_part as prev_units, lead(units) over w_part as next_units, lead(revenue) over w_part as next_revenue, lag(revenue) over w_part as prev_revenue, row_number() over w_part as event_seq from valid window w_part as (partition by store_id order by units, id)
